    if (Math.abs(g4.ty - g4.y) > 1.5) levels += '<line class="lvc ' + g4.c + '" x1="' + (W - PADR) + '" x2="' + (W - PADR + 4) + '" y1="' + f(g4.y) + '" y2="' + f(g4.ty) + '"/>';
